// ===== EDIT THESE TWO LINES ONCE =====
const REPO = 'gistmediawebsite/gist-site';
const SITE = 'https://www.gistmedia.org';
// =====================================
const b = $json.body || $json;
const need = ['title', 'description', 'body', 'section', 'image_url'];
const missing = need.filter(k => !b[k]);
if (missing.length) throw new Error('Missing fields: ' + missing.join(', '));
const sections = ['celebrity', 'music', 'movies', 'sport', 'events', 'luxury'];
if (!sections.includes(b.section)) throw new Error('section must be one of ' + sections.join(', '));
const slugify = s => String(s).toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 80).replace(/-$/, '');
const slug = b.slug ? slugify(b.slug) : slugify(b.title);
const now = new Date().toISOString();
const ext = (b.image_url.split('?')[0].match(/\.(jpe?g|png|webp)$/i) || [, 'jpg'])[1].toLowerCase();
const imagePath = `/img/news/${slug}-${Date.now().toString(36)}.${ext}`;
const q = s => JSON.stringify(String(s ?? ''));   // YAML-safe double-quoted string
const list = a => (Array.isArray(a) && a.length) ? '\n' + a.map(t => `  - ${q(t)}`).join('\n') : ' []';
const sources = Array.isArray(b.sources) && b.sources.length
  ? '\n' + b.sources.map(s => `  - name: ${q(s.name)}\n    url: ${q(s.url)}`).join('\n') : ' []';
const fm = [
  '---',
  `title: ${q(b.title)}`,
  `description: ${q(b.description)}`,
  `date: ${b.date || now}`,
  `updated: ${now}`,
  `section: ${b.section}`,
  `tags:${list(b.tags)}`,
  `image: ${imagePath}`,
  `image_alt: ${q(b.image_alt || b.title)}`,
  `image_credit: ${q(b.image_credit || 'GIST')}`,
  `author: ${q(b.author || 'GIST Desk')}`,
  `featured: ${b.featured ? 'true' : 'false'}`,
  `draft: ${b.draft ? 'true' : 'false'}`,
  `sponsored: ${b.sponsored ? 'true' : 'false'}`,
  b.sponsor ? `sponsor: ${q(b.sponsor)}` : null,
  b.disclosure ? `disclosure: ${q(b.disclosure)}` : null,
  `source: ${q(b.source || 'n8n')}`,
  b.source_url ? `source_url: ${q(b.source_url)}` : null,
  `sources:${sources}`,
  '---', '', String(b.body).trim(), ''
].filter(x => x !== null).join('\n');
return [{ json: {
  repo: REPO, slug, url: `${SITE}/news/${slug}/`,
  mdPath: `content/articles/${slug}.md`,
  mdB64: Buffer.from(fm, 'utf8').toString('base64'),
  imagePath, imageRepoPath: 'static' + imagePath, imageUrl: b.image_url,
  commitMsg: `Publish: ${b.title}`.slice(0, 120)
} }];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buf.length > 4.5 * 1024 * 1024) throw new Error('Image larger than 4.5 MB — resize before publishing');
return [{ json: { imgB64: buf.toString('base64') } }];
